SLIDES=[]
def add(title, sec, layout, items, takeaway, notes, refs='', visual='', cue=''):
    i=len(SLIDES)+1
    SLIDES.append(dict(n=i,title=title,sec=sec,layout=layout,items=items,takeaway=takeaway,notes=notes,refs=refs,visual=visual,cue=cue,part=1 if i<=5 else 2 if i<=19 else 3 if i<=26 else 4,speaker='甲' if i<=16 else '乙'))

add('合理用药：给宿舍药箱上堂课',45,'cover',['会选药 · 看成分 · 避误区','苏州大学｜选修课课堂展示','主讲：同学甲 / 同学乙'], '把每一次“吃什么药”，变成有依据的选择。',
'''甲：大家好。今天我们聊一个进入大学后越来越需要自己做决定的问题：身体不舒服时，药到底该怎么用？离开父母的提醒，宿舍药箱、室友推荐和手机搜索，可能成了我们的第一反应。但名字熟悉，不代表适合自己；药吃得多，也不代表好得快。接下来我们用五类校园情境和几轮举手选择，练习几个能直接用上的判断。我们不考药名，也不背剂量表，目标是学会看什么、问什么，以及什么时候应该就医。''',visual='蓝红白宿舍桌面插画：药盒、书本、水杯；原创可编辑矢量元素。',cue='甲主讲；乙操作翻页。')
add('室友感冒了，你先做哪一步？',90,'quiz',['A 先吃室友推荐的两种感冒药','B 先看症状、成分和注意事项','C 先加一粒抗生素，求个安心'], '举手选择 A / B / C｜暂不揭晓',
'''甲：先进入一个虚构情境。小苏明天有课，今天流鼻涕、喉咙不舒服，室友递来两盒感冒药，另一位室友说，加一粒抗生素更保险。现在只选第一步，不需要给出具体药名。请大家先用十秒看完三个选项。
【静默10秒】甲依次读A、B、C，每个选项留5秒举手。乙观察大致人数，不做精确统计，也不点名问理由。
甲：谢谢。无论你刚才选了哪个，今天都会解释这些选择背后的差别。选择B，是先获取决定所需的信息；这并不等于自己诊断所有疾病。我们先把答案放在心里，结束时再看看能否把这个动作做得更完整。''',visual='三张等宽选择卡；不突出正确选项。',cue='10秒阅读＋三轮举手约25秒；不追问个人用药史。')
add('合理用药，要同时过四关',60,'four',['安全｜关注禁忌与不良反应','有效｜针对真正需要解决的问题','经济｜避免不必要的花费','适宜｜适合这个人、这个时机'], '刚才选 B：先了解，再决定。',
'''甲：合理用药可以用四个词记住：安全、有效、经济、适宜。安全不是承诺任何药都没有风险，而是识别禁忌和可能的不良反应。有效，是药物针对的问题与实际需要相符。经济，是在满足治疗需要的前提下，避免不必要的药物和花费。适宜，则提醒我们，同一个药对室友合适，对自己不一定合适，年龄、过敏史、正在使用的其他药物，都可能影响选择。所以开场选B，是先把这些信息补齐，而不是看到一个症状就直接往药箱里伸手。''','S1',visual='四象限原则卡；每格一个关键词和一个简短解释。')
add('高中生物连接：药物也要找“靶点”',60,'target',['受体：接收信号的蛋白质','酶：参与并催化化学反应','药物：可能改变信号或反应过程'], '结构与功能有关｜靶点也可能分布在多个部位',
'''甲：回忆高中生物，我们学过蛋白质的结构与功能，也学过酶和细胞间的信息传递。理解药物，可以先用一个简化模型：有些药物与受体结合，改变信号；有些药物影响酶的作用，改变某个反应过程。图中用形状匹配表示识别，它只是一种示意，并不是所有药物都像一把钥匙只开一把锁。相同或相关的靶点可能存在于多个部位，所以治疗作用和其他作用可能同时出现。稍后讲抗过敏药为什么让人困，就会用到这个思路。''','S8',visual='可编辑“药物—受体—信号”示意，标注简化模型、非比例。')
add('今天的路线：从会判断，到会行动',45,'agenda',['01 基本原则｜5分钟','02 宿舍误区｜17分钟','03 安全用药｜8分钟','04 选择挑战｜5分钟'], '全程约35分钟，已包含举手互动。',
'''甲：今天分四部分。我们已经用五分钟建立基本原则，接着用十七分钟看宿舍里容易遇到的五类误区：重复成分、抗生素、备考提神、抗过敏药，以及药物与饮酒。然后用八分钟把知识变成一套操作方法，最后五分钟做一道简单综合题。甲负责前半段，乙负责后半段；投票时另一位同学帮忙观察。大家只需要做选择，不必临时组织一段观点，也不需要公开自己的疾病或用药经历。''',visual='四段路线图，时间比例示意。')
add('案例①：两盒感冒药，真是“双保险”？',75,'case',['小苏：一盒治头痛，一盒治感冒','室友：名字不同，应该能一起吃？','先暂停：翻到“成分”一栏'], '虚构情境｜包装不同，成分可能重复。',
'''甲：第一幕还是小苏。他拿到两盒药，一盒包装强调缓解头痛，一盒写着缓解感冒症状，于是直觉上觉得，一个管头，一个管感冒，应该互不冲突。但宣传的症状不同，不代表里面的有效成分不同。比如，对乙酰氨基酚既可以作为单一成分用于解热镇痛，也可能出现在复方感冒药里。两盒一起吃时，身体接收到的是所有来源的总量。我们在这里不推荐具体品牌，也不演示个人用药剂量，先练最重要的动作：把两份说明书的成分栏摆在一起比较。包装上的大字可以吸引注意，成分栏才是判断重复的依据。''','S2',visual='人物气泡＋两个匿名药盒；均为教学道具。')
add('看成分，才能发现“隐形重复”',60,'labels',['药盒A｜对乙酰氨基酚','药盒B｜对乙酰氨基酚＋其他成分','同一成分，会从不同药盒汇合'], '通用名 / 成分优先于商品名｜示意标签，不是实际说明书',
'''甲：这两个标签是教学示意，不对应具体产品。请看红色框出的同一个名字：对乙酰氨基酚。即使两盒药的商品名、用途描述和包装颜色不同，这个成分仍然会重复进入体内。判断时，不能把药盒当作两个互不相关的单位。特别是复方药，一盒里就可能有多种有效成分，所以更需要逐项核对。看到重复后，先不要自行叠加；拿着具体药名、规格和已经服用的时间，向药师确认。如果怀疑已经超量，也不能因为暂时没有不舒服就继续等，应及时获得医疗帮助。''','S2',visual='两张可编辑药盒成分标签，红框突出同名成分，箭头汇合。')
add('真实研究：模拟用药，也容易出错',60,'errorchart',['23.8%｜单一产品模拟用量超标','45.6%｜模拟联用出现重复超量'], '两项指标可能重叠，不能相加；不是实际中毒率。',
'''甲：我们用一项研究说明，读懂药品标签并没有想象中简单。研究发表于2012年，纳入美国门诊的500名成人，让他们完成非处方对乙酰氨基酚产品的模拟用药任务。23.8%的参与者在单一产品任务中安排出了超过研究判定阈值的用量，45.6%在联用任务中出现重复成分造成的潜在超量。请注意，这是模拟任务，不代表这些人实际中毒，更不能推算我们班或中国大学生的发生率。两项指标也可能来自同一名参与者，所以不能相加。我们从图中带走的结论是：核对成分需要一个具体动作，不能只靠“我应该记得”。''','S3',visual='PowerPoint原生可编辑水平条形图，0—100%；标出美国、n=500、2012。')
add('选择题②：两盒都含相同成分，怎么办？',75,'quiz',['A 商品名不同，可以照常同服','B 两种各减一半，自己调一调','C 暂不叠加，核对说明书并问药师'], '请选最稳妥的下一步｜答案在下一页',
'''甲：现在把刚才学到的动作再练一次。已知两盒药都含有对乙酰氨基酚，我们仍然不知道具体规格、适用人群，也不知道小苏还吃过什么。三个选项中，哪一个最稳妥？请先安静想十秒。
【静默10秒】甲依次读A、B、C，乙观察举手，各留5秒。
甲：这题不需要计算药量。特别留意B，它看起来很谨慎，因为把量减了，但它仍然是在缺少信息时自行拼接方案。我们今天练的是先识别风险，再补齐信息，而不是凭感觉把两盒药重新配方。下一页揭晓。''','S2',visual='三个等权选项，保持与第一题相同的布局。',cue='阅读10秒；举手约25秒；其余时间复述问题并转场。')
add('答案 C：先核对，再决定',30,'answer',['同成分：先不自行叠加','规格、时间、已服药物：一起核对','拿不准：带包装或照片问药师'], '少猜一步，就少一个出错机会。',
'''甲：答案是C。A忽略了成分，B在不知道规格和总量时自行改方案，二者都不可靠。C把操作顺序摆正：先不叠加，再核对，必要时请药师判断。询问时最好带上包装或清晰照片，同时说清已经吃过什么、吃了多少和什么时候吃的，这样对方才能给出有依据的建议。''','S2',visual='大号C与三步行动箭头。')
add('案例②：抗生素，不是感冒的通用答案',75,'microbes',['细菌｜具有细胞结构','病毒｜没有细胞结构，依赖宿主复制','抗生素｜针对细菌的某些结构或过程'], '普通感冒通常由病毒引起；是否需要抗生素，由医生判断。',
'''甲：第二个误区是把抗生素当成感冒时的保险药。回到高中生物，细菌具有细胞结构，病毒没有完整的细胞结构，需要利用宿主细胞复制。不同类别的抗生素，可以作用于细菌的细胞壁合成、蛋白质合成等过程；对引起普通感冒的病毒，它们没有相应的治疗作用。所以流鼻涕、嗓子痛，并不能自动推出“应该吃抗生素”。当然，出现这些症状也可能有其他原因，少数病毒感染之后还可能发生细菌感染，是否需要抗生素需要评估。我们能做的是描述症状、接受判断，而不是自己拿剩药试试看。''','S4; S11',visual='原创细菌与病毒矢量插画；清楚标注细胞壁为部分抗生素靶点。')
add('耐药：被筛选出来的是细菌',80,'selection',['原有差异｜少数细菌具有耐药性','选择压力｜敏感细菌更易被抑制','存活与繁殖｜耐药菌比例可能上升'], '连接高中生物：变异＋选择｜不是“人吃出了耐药体质”。',
'''甲：为什么不必要地用抗生素还会带来后续问题？可以借助高中生物的自然选择来理解。图中蓝色代表敏感细菌，红色代表具有耐药性的细菌。这些差异可以来自遗传变异，也可以来自耐药基因的获得。面对某种抗生素，敏感细菌更容易被抑制，具有相应耐药性的细菌可能存活并繁殖，于是群体中耐药菌的比例上升。图中的数量是教学示意，不是实验数据。这里最容易说错的一句话是“我的身体耐药了”。更准确地说，是病原菌对药物产生了抵抗能力。这个过程还涉及基因传播等因素，今天先记住选择压力这一条主线。''','S4; S5',visual='三阶段细菌群落示意；红色耐药菌数量标注为概念模型，不作真实比例。')
add('耐药风险，有多大？看清数据口径',70,'amrchart',['495万｜与细菌耐药相关的死亡','127万｜归因于细菌耐药的死亡'], '2019年全球估计｜两种口径，不可相加。',
'''甲：这里用的是2022年发表于《柳叶刀》的研究，对2019年全球细菌耐药负担进行估计。较宽的“相关”口径约为495万例死亡，而“归因”口径约为127万例。两者的比较假设不同：前者比较没有这类耐药感染的情况，后者比较感染仍然发生、但细菌对药物敏感的情况。它们不能相加，也不能理解为所有死亡都由个人乱吃抗生素造成。图上的细线是不确定性区间，提醒我们这些数字是模型估计，不是精确清点。我们引用这组历史数据说明耐药问题的重要性，并不把它称为今年的最新统计。''','S5',visual='带95%不确定性区间的水平条形图；单位万人，轴从0起；注明数据年2019、发表年2022。')
add('抗生素的三条行动规则',55,'three',['不自行启用｜先明确是否需要','不分享剩药｜相似症状不等于相同病因','按处方使用｜不擅自停、加或延长'], '出现不良反应或疗效疑问，及时联系医生 / 药师。',
'''甲：回到我们自己能做的事，记住三条。第一，不因为感冒或嗓子痛就自行启用抗生素。第二，不把自己剩下的药分给室友，也不拿室友的处方照着用。第三，确实需要时按医生给出的剂量、间隔和疗程使用，不因为感觉好一点就自行停药，也不为了“彻底一点”擅自延长。这里不是让大家出现严重反应也硬撑着吃完，而是出现异常、疗效不理想，或不知道该如何继续时，及时联系医生或药师，由专业人员调整方案。''','S4',visual='三张行动卡配药盒、分享禁止、时钟图标。')
add('案例③：“备考外挂”，真的值得试？',60,'case',['保健食品｜不能代替药物治疗疾病','“提高考试成绩”｜警惕夸大宣传','处方兴奋剂｜不借药、不自行购买服用'], '清醒感，不等于学习效果的保证。',
'''甲：第三个情境发生在考试周。小苏看到“提升专注、快速提分”的宣传，又听说有人借用治疗注意缺陷多动障碍的处方药来熬夜。这里要分开看：保健食品与药品不是一回事，不能用保健食品替代疾病治疗，也不能把某种功能声称直接等同于提高考试成绩。而处方兴奋剂有明确适应证，非医疗使用存在失眠、焦虑、成瘾及过量等风险，不能因为别人说有效就借来试。对需要这些药物的患者，规范治疗有价值；我们反对的是把别人的处方当作通用学习工具。''','S6; S7',visual='宿舍书桌与广告气泡插画；红色警示围绕“提分保证”，不展示品牌。')
add('案例④：鼻子舒服了，上课却困了',75,'case',['部分抗组胺药｜可能引起嗜睡','“较少嗜睡”｜不代表人人都不困','困倦时｜避免驾驶、骑车等高风险活动'], '不能仅凭“抗过敏药”四个字判断影响。',
'''甲：第四幕，小苏为了缓解过敏症状服了药，鼻子舒服了，坐进教室却特别想睡觉。这并不一定是药物没有起效，而可能是某些抗组胺药带来的嗜睡作用。有些药更容易让人困，有些相对较少，但个人反应也有差异。因此，选择时要说清自己的需求，例如白天有课、需要通勤，并向药师询问是否容易嗜睡。第一次使用时尤其应留意反应，困倦或反应变慢时，不要驾驶、骑车或做其他需要高度警觉的活动。也不要自己用酒精或其他药物去“抵消”这种感觉。
甲：为什么一种药既影响鼻子，也影响清醒程度？下面交给乙，接着用生物知识解释。''','S8',visual='清醒与困倦的同一人物对照；月牙眼和书本均为矢量元素。',cue='此页末交接。甲累计16分55秒；乙从第17页开始。')
add('同一条信号，在不同部位有不同作用',65,'target',['组胺＋受体｜参与过敏反应','脑内组胺信号｜也参与清醒状态','部分药物进入脑内｜可能引起嗜睡'], '这是简化机制图；不能据此自行换药。',
'''乙：接着刚才的问题。组胺是一种参与信号传递的物质，在外周组织中，它参与部分过敏症状；在脑内，相关信号也参与维持清醒状态。部分抗组胺药能够进入脑内，影响相应的受体作用，因此在缓解过敏症状的同时，也可能让人困倦。这里可以连接高中生物中的信息传递和内环境：同一种信号分子，在不同位置可能参与不同功能。我们把复杂机制压缩成这张示意图，是为了说明作用为什么可能同时发生，而不是让大家按这张图自行选择药物或调整剂量。''','S8; S14',visual='外周与脑内双路径示意；受体、箭头及说明可编辑。')
add('案例⑤：聚餐的酒，先缓一缓',120,'drinks',['酒精＋部分抗过敏药｜嗜睡与反应受损风险增加','酒精＋某些药物｜可能增加其他不良反应风险','普通口服片剂 / 胶囊｜通常用白水，具体看说明书'], '拿不准能否饮酒：先不喝，再查说明书或问药师。',
'''乙：第五个情境是聚餐。小苏白天吃了药，晚上被劝“就喝一点”。判断能不能一起用，不能只凭酒量，也不能只靠“上次没事”。酒精可能与多种药物相互作用，特别是与具有镇静作用的药物一起使用时，可能进一步影响警觉性和协调能力。对某些药物，风险还可能涉及肝脏、胃肠道等，但不同药物的机制和影响并不一样。
还有一个常见想法：把喝酒和吃药错开两小时就安全。这个时间不能通用，因为不同药物在体内停留的时间不同，饮酒情况和个体差异也会影响结果。拿不准时，最直接的行动是先不喝，带着具体药名去确认。
顺便说说送服药物。普通口服片剂和胶囊通常选择白水，并按说明书要求服用；不要默认咖啡、果汁、牛奶都能替代。但剂型有差别，例如含服或咀嚼的药物有自己的要求，所以最终仍然要看这盒药的具体说明。''','S8; S9; S13',visual='水杯、酒杯和药盒原创插画，搭配“先确认”的暂停标记。')
add('选择题③：聚餐前，选哪条路线？',120,'quiz',['A 已经吃过药，统一等两小时再喝酒','B 看具体药品要求；拿不准就先不喝','C 只要不醉，就不会与药物相互作用'], '背景：今天服了抗过敏药，具体饮酒要求尚未确认。',
'''乙：这一题仍然只选下一步。今天已经服过抗过敏药，但没有确认具体药品的饮酒要求，晚上聚餐时怎样做更合适？请大家看完三个选项，可以和旁边同学小声商量二十秒，只需要最后选一个字母。
【同桌讨论20秒】甲负责依次示意A、B、C，乙主持，给每个选项约5秒举手。
乙：这里有两个很容易误导人的线索，一个是时间，一个是醉不醉。药物相互作用不能靠统一间隔来排除，也不是只有喝醉才可能发生。正确答案是B：看这一个具体药品的要求；如果暂时不能确认，先不喝。即使全班都选对，也值得保留这个动作，因为聚餐时的社交压力容易让人把已经知道的原则放到一边。现在五个情境都看过了，我们把它们整理成一个可以重复使用的方法。''','S8; S9',visual='同一三选一模板；正确答案仅在讲者备注中，下一页给出行动结论。',cue='同桌讨论20秒＋举手约25秒；答案口头公布，不追问开放观点。')
add('安全用药四步：看、核、问、记',60,'four',['看｜症状、说明书、就医信号','核｜成分、剂量、间隔、禁忌','问｜医生 / 药师，确认不确定处','记｜药名、时间、用量与反应'], '上一题选 B｜把“不确定”变成一个咨询动作。',
'''乙：第三部分，我们把前面的例子浓缩成四个动作：看、核、问、记。看，是观察症状，也看说明书和需要就医的信号。核，是核对成分有没有重复，剂量与时间是否符合要求，自己有没有相关禁忌。问，是把不确定的地方交给医生或药师确认，不用猜测填空。记，是记录已经用过的药、时间、用量以及出现的反应。上一题选B，就把“这盒药能不能配酒”的不确定性变成了一个清楚的咨询问题。这四步是课堂助记法，不是替代诊疗的专业流程。''','S1; S2; S8; S9',visual='原创四步流程，标注“课堂助记法”。')
add('说明书很长？先定位这六处',90,'leaflet',['成分 / 通用名','适应证或功能主治','用法用量','禁忌与注意事项','相互作用 / 不良反应','贮藏条件 / 有效期'], '六处是阅读起点，不代表其余内容可以跳过。',
'''乙：看到密密麻麻的说明书，不少人的反应是只找“一次几片”。更有效的办法，是先定位六类信息。第一，成分和通用名，解决“我究竟在吃什么”。第二，适应证，确认它用于什么情况。第三，用法用量，包含每次多少、间隔多久以及如何服用。第四，禁忌和注意事项，查看过敏史、既往疾病和特殊人群等相关要求。第五，相互作用与不良反应，看看与其他药物、食物饮料是否存在需要注意的地方。第六，贮藏条件和有效期，确认药品是否仍适合使用。
这张是重新设计的阅读示意，不是实际产品的说明书，也不能替代完整说明书。如果处方要求与自己的理解不一致，应向开方医生或药师核实，而不是自己随意选一种理解执行。''','S1; S2; S8',visual='一张放大的原创示意说明书，六个编号定位区。')
add('时间、剂量、剂型，都别凭感觉改',70,'three',['漏服｜先查具体处理要求，不自行加倍','疗程｜按处方执行，有问题及时咨询','剂型｜缓释、肠溶等，不随意掰碎'], '不同药物要求不同；不要套用同一条补药规则。',
'''乙：用药过程中的很多问题，不是药选错了，而是自己改变了使用方式。比如漏了一次，不要自动理解成下次吃双倍。不同药物的处理方法不同，先查说明书，拿不准就问药师。再比如疗程，按处方使用，同时留意症状与反应；出现疑问要及时沟通，不能自行加量或延长。还有剂型，一些缓释或肠溶制剂依赖特定结构控制释放位置和速度，随意掰碎、咀嚼或打开胶囊，可能改变原先设计。也不是说所有带刻痕的药都不能分，而是能不能分、怎样分，应以具体产品说明为准。''','S10; S13; S4',visual='时钟、剂量格、完整片剂三幅矢量图。')
add('问药师时，把信息一次说清',60,'chat',['我有什么症状，持续多久？','我正在吃什么，何时吃了多少？','我有哪些过敏史、疾病或特殊情况？'], '带药盒 / 说明书照片，比“那种白色药片”更有用。',
'''乙：咨询是否有效，很大程度取决于我们提供的信息。可以按三句话组织。第一，我有什么症状，持续多久，正在变好还是加重。第二，我正在使用哪些药物或保健食品，具体药名和规格是什么，已经什么时候用了多少。第三，我有哪些已知药物过敏史、既往疾病或特殊情况。最好把药盒和说明书带上，或者拍清楚成分、规格和用法用量。只说“那种白色药片”，专业人员也难以准确判断。如果需要描述私密情况，可以单独咨询，不必在课堂或宿舍群里公开。''','S2; S1',visual='人物对话气泡与药盒照片框；三项信息清单。')
add('什么时候，不该继续自己试药？',75,'urgent',['呼吸困难 / 喉舌肿胀 / 意识异常｜立即急救','疑似超量或误服｜及时寻求医疗帮助','症状持续、加重或反复｜及时就诊'], '严重急症拨打120；带上药品信息，别等“自己好”。',
'''乙：合理用药还包括知道什么时候停止自己试错。用药后出现呼吸困难、喉部或舌头肿胀、明显意识异常等情况，可能是严重反应，应立即寻求急救，在国内拨打120。不要靠继续加药来压住症状。怀疑超量或误服，也要及时获得医疗帮助，有些问题并不一定马上表现出来。就诊时带上药盒和已经服用的时间、用量记录。如果不是急症，但症状持续、反复或越来越重，也应该按药品说明书的就医提示及时就诊。我们列的是几个重要信号，不是完整清单，更不是要大家在宿舍自行鉴别各种严重疾病。''','S2; S11; S12',visual='红色警示区＋120大字，三级行动卡；只列主要信号。')
add('宿舍药箱：留信息，也留秩序',65,'kit',['原包装＋说明书｜一起保留','有效期＋贮藏条件｜定期检查','个人用药记录｜不混装、不分享处方药'], '数量不求多；需要时能认清、查到、说清。',
'''乙：说到药箱，最重要的不是囤得多，而是需要时能认清。药品尽量保留原包装和说明书，避免把不同药片混在一个没有标签的小盒子里。检查有效期，也检查包装上的贮藏要求，不能把“放冰箱”当作所有药物的统一保存方法。自己的处方药不要分享给室友，过期或不再需要的药品按当地药品回收或分类要求处理。再保留一个简单的用药记录，例如手机备忘录，写药名、时间、用量和反应。这样复诊或咨询时，信息会比凭印象回忆更准确。''','S2; S4',visual='可编辑药箱插画、原包装、说明书、手机记录卡。')
add('把五个误区，换成五个动作',60,'recap',['感冒药叠加 → 核对成分','感冒吃抗生素 → 先明确是否需要','备考“外挂” → 不借用处方药','抗过敏后困倦 → 查提示、避风险活动','吃药后聚餐 → 先确认饮酒要求'], '看、核、问、记：现在进入简单挑战。',
'''乙：在进入挑战前，我们把五个案例各换成一个动作。两盒感冒药放在面前，先核对成分。感冒后想到抗生素，先确认是否真正需要。备考时有人推荐所谓外挂，不借用别人的处方药，也不相信保证提分的宣传。吃抗过敏药后感到困倦，查看注意事项并避开风险活动。聚餐想喝酒，先确认具体药物的要求。我们没有要求大家记住几十个药名，而是练习在几个关键位置停一下。下面的小测只组合这些已经出现的动作，没有新知识，也不需要计算。''',visual='五行“场景→动作”映射；每行配一个小图标。')
add('综合挑战：小苏今晚怎么安排？',60,'finalcase',['已服：一种复方感冒药','准备：再加一盒药＋参加聚餐','当前：成分没核对，症状尚轻'], '虚构情境｜无呼吸困难、意识异常等急症表现。',
'''乙：最后进入综合挑战，小苏再次登场。这次信息更完整：他今天已经服用一种复方感冒药，晚上觉得还没完全舒服，想再加另一盒，同时准备去聚餐。现在两盒药的成分没有核对，饮酒要求也不清楚，症状目前较轻，没有我们刚才提到的严重急症表现。这里不要求大家诊断他得了什么病，也不要求给他开药，只选一个更稳妥的下一步方案。请记住三个线索：已经服过药、还没核对成分、聚餐可能喝酒。下一页有三个方案，答案不会藏在复杂医学知识里。''',visual='三张线索卡：已服、待核、聚餐；小苏人物复用。')
add('你会替小苏选哪个方案？',90,'quiz',['A 两盒一起吃，聚餐少喝一点','B 先核对成分，拿不准问药师；先不喝酒','C 加抗生素预防一下，明天再看'], '单选 A / B / C｜想10秒，然后举手',
'''乙：请看三个方案。A，两盒一起吃，聚餐少喝一点。B，先核对成分，拿不准问药师，在没有确认之前先不喝酒。C，加抗生素预防一下，明天再看。大家先自己想十秒。
【静默10秒】甲依次邀请选A、B、C的同学举手，每个选项约5秒；乙观察，不要求任何人解释。
乙：这一题里，B包含的都是我们已经练过的动作；A和C则各自跳过了关键信息。请保留自己的选择，下一页我们按三条线索逐项核对。即使刚才已经猜到答案，也可以再看一遍：你是凭“这个选项最长”选的，还是确实找到了成分、酒精和抗生素三个判断点？''',visual='三张等权选择卡，B不过度加粗，避免提前暗示答案。',cue='阅读10秒＋举手约25秒；甲负责观察，乙主讲。')
add('答案 B：三个判断点，全都用上了',90,'answer',['成分未核对 → 先不自行叠加','饮酒要求不明 → 先不喝，查询确认','没有用药依据 → 不自行加抗生素'], '若症状加重或出现急症信号，应及时就医。',
'''乙：答案是B。我们把题目拆成三步。第一，另一盒药成分不清楚，不能因为症状还在就直接叠加。第二，具体药物的饮酒要求没有确认，先不喝比凭酒量判断更稳妥。第三，题目没有提供使用抗生素的依据，“预防一下”不能替代医生评估。这三条一起组成了更有依据的下一步。
甲：也补充一句，B不是要求小苏一直待在宿舍查说明书。如果症状持续、加重，或者出现呼吸困难、明显意识异常等情况，行动就应该转为及时就医或急救。
乙：所以合理用药不是背出一个永远适用的药方，而是根据已经掌握的信息，选对接下来的动作。今天这道题不难，目的是让大家能把这个顺序带回真实生活。''','S2; S4; S9; S11; S12',visual='大号B＋三个“线索→行动”映射。',cue='乙揭晓；甲补充就医边界约15秒，再交回乙。')
add('药可以常备，判断不能省略',60,'closing',['先看说明书，再做用药决定','核对重复成分，记录已服药物','拿不准，问医生 / 药师'], '会看 · 会核 · 会问 · 会记',
'''乙：最后，我们把今天的内容收在三句话里。第一，先看说明书，再做用药决定，不让包装和熟悉感替我们判断。第二，核对重复成分，并记录已经服用的药物、时间和用量。第三，遇到不确定的信息，向医生或药师询问；该就医的时候，不继续靠自己试药。
甲：希望下一次室友拿出药盒时，大家能多做一个核对动作，多问一个具体问题。
乙：药可以常备，判断不能省略。谢谢大家。我们的数据出处和参考资料放在后面的附页，方便课后查阅。
【留出约10秒结束停顿；不在35分钟内另加开放讨论。】''',visual='蓝底白字收尾，红色胶囊图形；复现开场视觉。',cue='甲乙共同收尾；参考文献附页不逐页讲解。')
